set search_path = public, extensions;


with r as (insert into public.roles (key, name, description, is_system) values ('super_admin', 'Super Admin', 'Full access to everything, including staff, roles and settings.', true) returning id)

with r as (insert into public.roles (key, name, description, is_system) values ('admin', 'Admin', 'Runs day-to-day ecommerce. Cannot manage staff, roles or core settings unless granted.', true) returning id)

with r as (insert into public.roles (key, name, description, is_system) values ('editor', 'Editor', 'Manages pages, homepage, journal, banners, collections, navigation, media and SEO.', true) returning id)

with r as (insert into public.roles (key, name, description, is_system) values ('author', 'Author', 'Writes journal posts and uploads media. Publishing is configurable.', true) returning id)

with r as (insert into public.roles (key, name, description, is_system) values ('fulfilment', 'Fulfilment', 'Processes and ships orders, handles returns and stock.', true) returning id)



select (select id from public.media_folders where name = 'Demo artwork'), '/demo/' || f, f, t, t, 'image', 'image/svg+xml',
  case when f like 'hero.svg' then 1920 when f like 'hero-mobile%' then 900 when f like 'editorial-2%' or f like 'custom-unit%' then 1600 when f like 'journal%' or f like 'editorial%' then 1200 when f like 'social%' then 900 else 800 end,
  case when f like 'hero.svg' then 1080 when f like 'hero-mobile%' then 1400 when f like 'editorial-2%' then 1000 when f like 'custom-unit%' then 1100 when f like 'journal%' then 800 when f like 'editorial%' then 1500 when f like 'social%' then 900 else 1000 end,
  array['demo']
