declare common jsonb := '{"care":"<p>Detangle gently from ends to roots with a wide-tooth comb. Co-wash every 7–10 wears with a sulphate-free shampoo and a moisturising conditioner. Let it air-dry flat or on a stand, and use a heat protectant before styling. Store in a silk bag, away from direct sunlight.</p>","shipping_note":"In-stock items dispatch from Lagos within 1–2 business days. Custom units dispatch after production. Delivery times and fees are calculated at checkout for your address.","returns_note":"Unworn, unaltered hair with its lace and wefts intact can be returned or exchanged under our Returns Policy. For hygiene reasons, worn, cut, coloured or custom items cannot be returned.","faq":[{"q":"Can I colour or bleach this hair?","a":"Yes — virgin and donor hair can be coloured by a professional. We recommend a strand test first. Coloured hair is not eligible for return."},{"q":"How long will it last?","a":"With the care routine above, our virgin hair typically lasts well over a year of regular wear. Donor hair lasts longer still."}]}'::jsonb; p jsonb; v jsonb; m jsonb; pid uuid; i int; pos int;
begin
  for p in select * from jsonb_array_elements('[{"n":"HairverGreen Signature Body Wave","s":"signature-body-wave","k":"HG-SBW","t":"hair","c":"virgin-hair","sh":"Our signature virgin body wave — soft S-waves, full ends and a natural lustre. Sold per bundle.","d":"<p>The texture we are known for. Signature Body Wave is unprocessed virgin hair with the cuticle intact and aligned, so it moves, shines and wears like your own. Double-wefted for fullness from root to end.</p><p>Wear the waves, or press it sleek — it returns to its pattern after washing.</p>","dt":{"origin":"Ethically sourced virgin hair","grade":"Signature","weight_per_bundle":"100g (±5g)","hair_info":"Unprocessed, cuticle-aligned, double-wefted. Can be coloured, bleached and heat-styled."},"tg":["bestseller","virgin","body wave","bundles","demo"],"ok":["texture","length"],"f":true,"nw":false,"rr":false,"w":110,"mp":8500000,"v":[["HG-SBW-BODYWAVE-12","Body Wave / 12\"",{"texture":"body-wave","length":"12"},8500000,null,4675000,true,12],["HG-SBW-BODYWAVE-14","Body Wave / 14\"",{"texture":"body-wave","length":"14"},10000000,null,5500000,true,12],["HG-SBW-BODYWAVE-16","Body Wave / 16\"",{"texture":"body-wave","length":"16"},11500000,null,6325000,true,12],["HG-SBW-BODYWAVE-18","Body Wave / 18\"",{"texture":"body-wave","length":"18"},13000000,null,7150000,true,12],["HG-SBW-BODYWAVE-20","Body Wave / 20\"",{"texture":"body-wave","length":"20"},14500000,null,7975000,true,3],["HG-SBW-BODYWAVE-22","Body Wave / 22\"",{"texture":"body-wave","length":"22"},16000000,null,8800000,true,12],["HG-SBW-BODYWAVE-24","Body Wave / 24\"",{"texture":"body-wave","length":"24"},17500000,null,9625000,true,12],["HG-SBW-BODYWAVE-26","Body Wave / 26\"",{"texture":"body-wave","length":"26"},19000000,null,10450000,true,12],["HG-SBW-BODYWAVE-28","Body Wave / 28\"",{"texture":"body-wave","length":"28"},20500000,null,11275000,true,12],["HG-SBW-BODYWAVE-30","Body Wave / 30\"",{"texture":"body-wave","length":"30"},22000000,24500000,12100000,t