g",{"texture":"kinky"}],["kinky-2.svg",{"texture":"kinky"}]]},{"n":"HairverGreen Custom Unit","s":"custom-unit","k":"HG-CUSTOM","t":"custom_unit","c":"custom-units","sh":"A unit made around you — texture, length, density, lace, colour and finish. Price shown is the starting price.","d":"<p>Tell us exactly how you want to feel, and we will build it. Choose your hair, lace and finish, and our team will confirm every detail with you before production begins.</p>","dt":{"construction":"Custom","production_time":"7–14 business days after confirmation"},"tg":["custom","wig","bespoke","demo"],"ok":[],"f":false,"nw":false,"rr":true,"w":400,"mp":45000000,"v":[["HG-CUSTOM","Default",{},45000000,null,null,false,0]],"m":[["custom-unit.svg",{}],["editorial-1.svg",{}]]},{"n":"Wig Care Kit","s":"wig-care-kit","k":"HG-KIT","t":"accessory","c":"accessories","sh":"Sulphate-free shampoo, conditioner, leave-in and a wide-tooth comb.","d":"<p>Everything you need to keep your hair soft and lustrous between wears.</p>","dt":{},"tg":["care","accessory","demo"],"ok":[],"f":false,"nw":false,"rr":false,"w":900,"mp":3800000,"v":[["HG-KIT","Default",{},3800000,null,1710000,true,25]],"m":[["care-kit.svg",{}]]},{"n":"Silk Storage Bag","s":"silk-storage-bag","k":"HG-BAG","t":"accessory","c":"accessories","sh":"A satin-lined storage bag with hanger to protect your unit between wears.","d":"<p>Keeps your hair tangle-free and dust-free, and holds its shape on the hanger.</p>","dt":{},"tg":["accessory","storage","demo"],"ok":[],"f":false,"nw":false,"rr":false,"w":200,"mp":1800000,"v":[["HG-BAG","Default",{},1800000,null,630000,true,40]],"m":[["storage-bag.svg",{}]]},{"n":"Build Your Bundle — 3 Bundles + Closure","s":"build-your-bundle","k":"HG-BYB","t":"bundle_deal","c":"bundles","sh":"Choose three bundles in any length and a matching closure — and save 12% on the set.","d":"<p>The complete install in one. Pick your three bundle lengths and your closure, and we will apply 12% off the total. Add a frontal for a further saving.</p>","dt":{},"tg":["bundle deal","save","demo"],"ok":[],"f":true,"nw":false,"rr":false,"w":0,"mp":0,"v":[["HG-BYB","Default",{},0,null,null,false,0]],"m":[["body-wave-3.svg",{}],["deep-wave-2.svg",{}]]},{"n":"The Glueless Essentials Set","s":"glueless-essentials-set","k":"HG-GES","t":"bundle_deal","c":"glueless-wigs","sh":"Signature Glueless Unit (Body Wave, 18\") with the Wig Care Kit and Silk Storage Bag.","d":"<p>Our best-selling glueless unit with everything you need to care for it — at a set price.</p>","dt":{},"tg":["bundle deal","glueless","gift","demo"],"ok":[],"f":false,"nw":false,"rr":false,"w":0,"mp":48500000,"v":[["HG-GES","Default",{},48500000,null,null,false,0]],"m":[["body-wave-1.svg",{}],["care-kit.svg",{}],["storage-bag.svg",{}]]}]'::jsonb) loop
      price, is_featured, is_new, requires_review, weight_grams, seo_description)
    values (p->>'n', p->>'s', p->>'k', p->>'t', (select id from public.categories where slug = p->>'c'), 'active', p->>'sh', p->>'d',
      common || (p->'dt'), array(select jsonb_array_elements_text(p->'tg')), array(select jsonb_array_elements_text(p->'ok')),
      (p->>'mp')::bigint, (p->>'f')::boolean, (p->>'nw')::boolean, (p->>'rr')::boolean, (p->>'w')::int, p->>'sh')
    returning id into pid;
    pos := 0;
    for v in select * from jsonb_array_elements(p->'v') loop
      values (pid, v->>0, v->>1, v->2, (v->>3)::bigint, nullif(v->>4,'')::bigint, nullif(v->>5,'')::bigint, pos, (v->>6)::boolean, (v->>7)::int, (p->>'w')::int, 2);
      pos := pos + 1;
    end loop;
    i := 0;
    for m in select * from jsonb_array_elements(p->'m') loop
      values (pid, (select id from public.media where filename = m->>0), m->1, i);
      i := i + 1;
    end loop;
  end loop;
end $seed$;

