values ('how-to-choose-your-density', 'How to choose the right density', 'Density is the single biggest factor in how natural — or how glamorous — your unit looks. Here is how to choose.', '<p>Density describes how much hair is ventilated onto the cap. It is the difference between a unit that looks like it grew from your scalp and one that turns heads from across the room.</p><h2>150% — natural and light</h2><p>Closest to most people''s natural hair. Comfortable in warm weather and ideal for shorter lengths.</p><h2>180% — everyday fullness</h2><p>Our most popular choice. Full enough to look polished, light enough to wear all day.</p><h2>200–220% — full glamour</h2><p>For volume and drama, especially on longer lengths where hair naturally thins towards the ends.</p><h2>A simple rule</h2><p>The longer the length, the more density you will want to keep the ends looking full.</p>', (select id from public.blog_categories where slug = 'hair-guides'), (select id from public.media where filename = 'journal-1.svg'), 'Hairver Green Editorial', 'published', now() - interval '5 days',
  coalesce((select array_agg(id) from public.products where slug = any(array['ready-to-wear-unit','signature-glueless-unit']::text[])), '{}'), 3, 'Density is the single biggest factor in how natural — or how glamorous — your unit looks. Here is how to choose.', array['demo']::text[]);

values ('caring-for-body-wave-hair', 'Caring for body wave hair', 'Keep your body wave soft, defined and tangle-free for longer with this simple routine.', '<p>Body wave is our signature texture for a reason — it is soft, versatile and forgiving. A few habits keep it that way.</p><h2>Wash less, condition more</h2><p>Co-wash every 7–10 wears with a sulphate-free shampoo, and always follow with a moisturising conditioner.</p><h2>Detangle from the ends</h2><p>Use a wide-tooth comb and work upwards from the ends to the roots, holding the hair above the section you are combing.</p><h2>Let the pattern come back</h2><p>After washing, rake a light leave-in through with your fingers and let it air-dry. The wave returns on its own.</p>', (select id from public.blog_categories where slug = 'hair-care'), (select id from public.media where filename = 'journal-2.svg'), 'Hairver Green Editorial', 'published', now() - interval '10 days',
  coalesce((select array_agg(id) from public.products where slug = any(array['signature-body-wave','wig-care-kit']::text[])), '{}'), 3, 'Keep your body wave soft, defined and tangle-free for longer with this simple routine.', array['demo']::text[]);

values ('closure-vs-frontal', 'Closure or frontal: which is right for you?', 'Both give you a natural parting — the difference is how much freedom you want.', '<p>Closures and frontals both finish an install with a natural-looking parting. The choice comes down to how you like to style.</p><h2>Closures</h2><p>A 4×4, 5×5 or 6×6 square of lace that covers the parting area. Lower maintenance and easy to install.</p><h2>Frontals</h2><p>A 13×4 or 13×6 lace that runs ear to ear. It gives a full hairline, so you can part anywhere and wear the hair off your face.</p>', (select id from public.blog_categories where slug = 'hair-education'), (select id from public.media where filename = 'journal-3.svg'), 'Hairver Green Editorial', 'published', now() - interval '15 days',
  coalesce((select array_agg(id) from public.products where slug = any(array['hd-lace-closure','hd-lace-frontal']::text[])), '{}'), 3, 'Both give you a natural parting — the difference is how much freedom you want.', array['demo']::text[]);

values ('welcome-to-hairver-green', 'Welcome to Hairver Green', 'A luxury hair house, from Lagos to wherever life takes you.', '<p><em>Replace this post with your own story.</em> This is where you can introduce the Hairver Green studio, the people behind it and the craft that goes into every piece.</p>', (select id from public.blog_categories where slug = 'hairver-green-stories'), (select id from public.media where filename = 'journal-4.svg'), 'Hairver Green Editorial', 'published', now() - interval '20 days',
  coalesce((select array_agg(id) from public.products where slug = any(array[]::text[])), '{}'), 3, 'A luxury hair house, from Lagos to wherever life takes you.', array['demo']::text[]);

