insert into public.page_sections (page_id, type, name, sort, settings) values ((select id from public.pages where slug = 'home'), 'hero', 'Hero', 0, '{"eyebrow":"Luxury Hair House · Lagos","heading":"Luxury hair. Beautifully yours.","text":"Premium virgin hair, donor hair, custom units and ready-to-wear wigs, crafted for effortless beauty.","media":{"kind":"image","url":"/demo/hero.svg","alt":"Flowing hair strands in champagne gold on emerald"},"mobile_media":{"kind":"image","url":"/demo/hero-mobile.svg","alt":""},"ctas":[{"label":"Shop wigs","href":"/wigs","style":"primary"},{"label":"Shop hair","href":"/hair","style":"secondary"}],"align":"left","height":"tall","overlay":0.25,"theme":"dark"}'::jsonb);
