insert into public.page_sections (page_id, type, name, sort, settings) values ((select id from public.pages where slug = 'home'), 'shop_the_look', 'Shop the look', 5, '{"heading":"Shop the look","eyebrow":"Editorial","media":{"kind":"image","url":"/demo/editorial-2.svg","alt":""},"products":["signature-glueless-unit","wig-care-kit","silk-storage-bag"],"text":"Our Signature Glueless Unit, finished and styled — with everything you need to keep it that way."}'::jsonb);
insert into public.page_sections (page_id, type, name, sort, settings) values ((select id from public.pages where slug = 'home'), 'collection_feature', 'Signature collection', 6, '{"eyebrow":"The Signature Collection","heading":"Made to be noticed.","text":"The textures and units that define Hairver Green — selected, finished and checked by hand in our Lagos studio.","collection":"signature","media":{"kind":"image","url":"/demo/editorial-3.svg","alt":""},"cta":{"label":"Discover the collection","href":"/collections/signature"},"theme":"dark"}'::jsonb);
insert into public.page_sections (page_id, type, name, sort, settings) values ((select id from public.pages where slug = 'home'), 'value_props', 'Why Hairver Green', 7, '{"heading":"Why Hairver Green","items":[{"title":"Premium hair","text":"Virgin and single-donor hair, selected strand by strand.","icon":"sparkle"},{"title":"Expert craftsmanship","text":"Every unit is constructed, plucked and finished by hand in Lagos.","icon":"scissors"},{"title":"Global shipping","text":"Tracked delivery across Nigeria and worldwide.","icon":"globe"},{"title":"Personal service","text":"Real people, on hand to help you choose.","icon":"heart"}]}'::jsonb);
insert into public.page_sections (page_id, type, name, sort, settings) values ((select id from public.pages where slug = 'home'), 'process_steps', 'Custom unit experience', 8, '{"eyebrow":"Custom units","heading":"Crafted around you.","text":"A unit built to your measurements, texture and style — confirmed with you at every step.","steps":[{"title":"Consultation","text":"Tell us the look and feel you want."},{"title":"Selection","text":"Choose your hair, lace and density."},{"title":"Customisation","text":"Colour, parting, plucking and finish."},{"title":"Crafting","text":"Built by hand in our Lagos studio."},{"title":"Delivery","text":"Styled, checked and sent to you."}],"media":{"kind":"image","url":"/demo/custom-unit.svg","alt":""},"cta":{"label":"Create your custom unit","href":"/services/custom-units"}}'::jsonb);
