insert into public.page_sections (page_id, type, name, sort, settings) values ((select id from public.pages where slug = 'about'), 'hero', 'About hero', 0, '{"eyebrow":"Our story","heading":"A luxury hair house, born in Lagos.","text":"We make hair for women who know exactly how they want to feel.","media":{"kind":"image","url":"/demo/editorial-3.svg","alt":""},"height":"medium","align":"center","overlay":0.3,"theme":"dark"}'::jsonb);
insert into public.page_sections (page_id, type, name, sort, settings) values ((select id from public.pages where slug = 'about'), 'rich_text', 'Story', 1, '{"html":"<p><em>Replace this with the Hairver Green story.</em> Use this space to share how the brand began, who is behind it and what you believe beautiful hair should feel like.</p><p>Talk about how you select your hair, how units are made in your Lagos studio, and the care you put into every order that leaves it.</p>","width":"narrow"}'::jsonb);
insert into public.page_sections (page_id, type, name, sort, settings) values ((select id from public.pages where slug = 'about'), 'value_props', 'Values', 2, '{"heading":"What we stand for","items":[{"title":"Authenticity","text":"Honest descriptions of every texture, grade and origin."},{"title":"Craft","text":"Hand-finished units, checked before they leave the studio."},{"title":"Care","text":"Guidance before and after you buy."}]}'::jsonb);
