insert into public.pages (slug, title, kind, status, body, seo_description, published_at) values ('hair-guide', 'Hair Guide', 'page', 'published', null, 'How to choose texture, length, lace and density — the Hairver Green hair guide.', now());
insert into public.page_sections (page_id, type, name, sort, settings) values ((select id from public.pages where slug = 'hair-guide'), 'hero', 'Guide hero', 0, '{"eyebrow":"Hair guide","heading":"Choose with confidence.","text":"Texture, length, lace and density — explained simply.","media":{"kind":"image","url":"/demo/editorial-1.svg","alt":""},"height":"short","align":"center","overlay":0.35,"theme":"dark"}'::jsonb);
insert into public.page_sections (page_id, type, name, sort, settings) values ((select id from public.pages where slug = 'hair-guide'), 'texture_guide', 'Texture guide', 1, '{"heading":"Texture guide","eyebrow":"Compare"}'::jsonb);
insert into public.page_sections (page_id, type, name, sort, settings) values ((select id from public.pages where slug = 'hair-guide'), 'length_guide', 'Length guide', 2, '{"heading":"Length guide","text":"Lengths are measured straight, from the top of the weft to the tips. Curly and wavy textures will look shorter than their stretched length."}'::jsonb);
insert into public.page_sections (page_id, type, name, sort, settings) values ((select id from public.pages where slug = 'hair-guide'), 'faq', 'Lace & density', 3, '{"heading":"Lace, density & construction","items":[{"q":"What is the difference between a closure and a frontal?","a":"A closure is a square piece of lace (4×4, 5×5 or 6×6) that covers the parting area. A frontal runs ear to ear (13×4 or 13×6), giving you a full hairline and more parting freedom."},{"q":"What does HD lace mean?","a":"HD lace is an ultra-thin, transparent Swiss lace that blends with every skin tone and is almost invisible on the skin."},{"q":"Which density should I choose?","a":"150% is light and natural, 180% is our most popular everyday fullness, and 200–220% gives a full, glamorous look."},{"q":"What is a glueless unit?","a":"A unit designed to be worn without adhesive. It uses an elastic band, combs and a pre-cut lace so you can wear it securely and remove it without damage."},{"q":"How many bundles do I need?","a":"For a full sew-in, we recommend three bundles for 10\"–20\", and three to four bundles for 22\" and longer, plus a closure or frontal."}]}'::jsonb);
insert into public.page_sections (page_id, type, name, sort, settings) values ((select id from public.pages where slug = 'hair-guide'), 'rich_text', 'Care', 4, '{"heading":"Hair care","html":"<p>Detangle gently from ends to roots with a wide-tooth comb. Co-wash every 7–10 wears with a sulphate-free shampoo and moisturising conditioner. Air-dry flat or on a stand, use heat protectant before styling, and store your unit in a silk bag.</p>","width":"narrow"}'::jsonb);
insert into public.pages (slug, title, kind, status, body, seo_description, published_at) values ('faq', 'FAQ', 'page', 'published', null, 'Frequently asked questions about Hairver Green orders, shipping and hair care.', now());
insert into public.page_sections (page_id, type, name, sort, settings) values ((select id from public.pages where slug = 'faq'), 'faq', 'FAQ', 0, '{"heading":"Frequently asked questions","items":[{"q":"How do I pay?","a":"Checkout is secured by Paystack. Depending on availability you can pay by card, bank transfer, USSD, bank account and other supported channels."},{"q":"Do you ship internationally?","a":"Yes. Shipping options and costs for your country are shown at checkout."},{"q":"How do I track my order?","a":"You will receive tracking details by email when your order ships. You can also use the Track Order page or your account."},{"q":"Can I return my hair?","a":"Please read our Refund Policy for eligibility. Worn, cut, coloured or custom items cannot be returned."},{"q":"How long do custom units take?","a":"Custom units are made to order. We confirm your configuration and timeline with you before production begins."}]}'::jsonb);
